package com.andye.warmod.icbm;
import com.andye.warmod.WarMod; import java.util.HashSet; import java.util.Set; import java.util.UUID; import net.minecraft.SharedConstants; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.ChunkPos; import net.minecraft.world.phys.Vec3;
public final class IcbmChunkTicketController { private final UUID missileId; private IcbmFlightPlan plan; private final Set<ChunkPos> held=new HashSet<>(); private Set<ChunkPos> separationWindow=Set.of(); private long separationReleaseElapsed=Long.MAX_VALUE; private boolean released; public IcbmChunkTicketController(IcbmFlightPlan plan){missileId=plan.missileId();this.plan=plan;rebuildSeparationWindow();} public void updatePlan(IcbmFlightPlan revised){if(!missileId.equals(revised.missileId()))throw new IllegalArgumentException("Missile identity changed");plan=revised;rebuildSeparationWindow();} public void update(ServerLevel level,long elapsed){if(released||(elapsed&1L)!=0)return;HashSet<ChunkPos>wanted=new HashSet<>();long boostEnd=(long)plan.ignitionTicks()+plan.boostTicks();if(elapsed<=boostEnd+IcbmConstants.BOOST_TICKET_TAIL_TICKS){Vec3 carrier=IcbmTrajectory.position(plan,elapsed);IcbmChunkTicketRegistry.addWindow(wanted,IcbmChunkTicketRegistry.chunk(carrier),IcbmConstants.CARRIER_CHUNK_RADIUS);}if(elapsed>=plan.separationTick()-IcbmConstants.SEPARATION_TICKET_LEAD_TICKS&&elapsed<separationReleaseElapsed)wanted.addAll(separationWindow);replace(level,wanted);} public boolean separationReady(ServerLevel level){return !separationWindow.isEmpty()&&IcbmChunkTicketRegistry.allLoaded(level,separationWindow);} public void markSeparated(long elapsed){separationReleaseElapsed=elapsed+IcbmConstants.SEPARATION_TICKET_TAIL_TICKS;} public void releaseAll(ServerLevel level){if(released)return;replace(level,Set.of());released=true;if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("ICBM {} released carrier tickets",missileId);} private void rebuildSeparationWindow(){HashSet<ChunkPos> window=new HashSet<>();IcbmChunkTicketRegistry.addWindow(window,IcbmChunkTicketRegistry.chunk(plan.separationPosition()),1);separationWindow=Set.copyOf(window);} private void replace(ServerLevel level,Set<ChunkPos>wanted){for(ChunkPos chunk:wanted)if(held.add(chunk))IcbmChunkTicketRegistry.acquire(level,chunk);for(ChunkPos chunk:Set.copyOf(held)){if(wanted.contains(chunk))continue;IcbmChunkTicketRegistry.release(level,chunk);held.remove(chunk);}} }